const verified=items=>(items||[]).filter(item=>item.verificationStatus==='verified'&&item.id&&item.source);
export function toJsonBundle(profile,draft) { const groundedProfile={contact:profile.contact,roles:verified(profile.roles).map(role=>({...role,accomplishments:verified(role.accomplishments)})),skills:verified(profile.skills),tools:verified(profile.tools),metrics:verified(profile.metrics),certifications:verified(profile.certifications),education:verified(profile.education),projects:verified(profile.projects),summaryVariants:verified(profile.summaryVariants)};return JSON.stringify({schemaVersion:1,groundedOnly:true,provenancePolicy:'verified-only',profile:groundedProfile,draft},null,2); }
